const analyticsLocaleOverrides = Object.fromEntries(
  SUPPORTED_LOCALES.map((locale) => {
    const copy = rawAnalyticsLocaleOverrides[locale];
    const text = (key: keyof TranslationMap) => copy[key] ?? enBase[key];

    return [locale, {
      ...copy,
      videoAnalyticsOverviewLoading: copy.videoAnalyticsOverviewLoading ?? text("videoAnalyticsOverview"),
      videoAnalyticsOverviewFailed: copy.videoAnalyticsOverviewFailed ?? text("videoAnalyticsOverview"),
      videoAnalyticsTotalViewsHelp: copy.videoAnalyticsTotalViewsHelp ?? text("videoAnalyticsTotalViews"),
      videoAnalyticsFirstTimeViewsHelp: copy.videoAnalyticsFirstTimeViewsHelp ?? text("videoAnalyticsFirstTimeViews"),
      videoAnalyticsWatchTimeHelp: copy.videoAnalyticsWatchTimeHelp ?? text("videoAnalyticsWatchTime"),
      videoAnalyticsTotalLikesHelp: copy.videoAnalyticsTotalLikesHelp ?? text("videoAnalyticsTotalLikes"),
      videoAnalyticsTotalDislikesHelp: copy.videoAnalyticsTotalDislikesHelp ?? text("videoAnalyticsTotalDislikes"),
      videoAnalyticsAverageWatchTimeHelp: copy.videoAnalyticsAverageWatchTimeHelp ?? text("videoAnalyticsAverageWatchTime"),
      videoAnalyticsTotalCommentsHelp: copy.videoAnalyticsTotalCommentsHelp ?? text("videoAnalyticsTotalComments"),
      videoAnalyticsAudienceLoading: copy.videoAnalyticsAudienceLoading ?? text("videoAnalyticsAudienceBreakdown"),
      videoAnalyticsAudienceFailed: copy.videoAnalyticsAudienceFailed ?? text("videoAnalyticsAudienceBreakdown"),
    }];
  })
) as unknown as Record<Locale, Partial<TranslationMap>>;

